import{z as n,x as s,o as A,c as i,q as e,j as o,D as a,d as r,s as t,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"开源配方对照","description":"","frontmatter":{"title":"开源配方对照","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-opensource-recipes.md","filePath":"llm/pf2-opensource-recipes.md","lastUpdated":1791063341000}'),p={name:"llm/pf2-opensource-recipes.md"};function m(d,E,c,h,C,D){const B=s("Mermaid");return A(),i("div",null,[E[2]||(E[2]=e('<h1 id="开源配方对照" tabindex="-1">开源配方对照 <a class="header-anchor" href="#开源配方对照" aria-label="Permalink to &quot;开源配方对照&quot;">​</a></h1><div class="epigraph"><p>模型报告是快照，配方才是可复现物；读报告的本事，是把快照还原回它背后的决策表。</p><footer>—— 据 OLMo 2（arXiv:2501.00656）全开放配方与 Llama 3 报告（arXiv:2407.21783）对照整理</footer></div><p><a href="/llm/pf2-compute-accounting">上一课</a>把全部决策换算成账。本课把这套配方框架拿去读公开工作：Llama 3、OLMo 2、FineWeb 这些公开配方，逐项对照本课程的要素表——哪些决策披露了、哪些只能猜、哪些连报告作者也没定死。数据配方的开放性见 <a href="/llm/dolma-fineweb">Dolma 与 FineWeb</a>；本课的对象是训练配方整表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读公开报告有两个方向性错误。一个是<strong>当菜谱抄</strong>：把报告里的超参数字抄进自己的配方，而不问那些数绑定在什么坐标系上——Llama 3 的 batch 与学习率绑定它的 15.6T token、特定序列长与稳定件组合，搬到不同的词表与算力预算上没有任何担保。另一个是<strong>当论文批</strong>：拿「报告没写种子」去否定整份报告——生产报告本来就不是可复现物，它的价值在于披露决策结构。对照的正确姿态介于两者之间：抽取<strong>决策</strong>而不是<strong>数字</strong>，标注每个决策的披露完整度。</p><p><span class="marginnote">「过训」就是在算力预算内故意训得比「计算最优」更久——参数相对偏小、token 相对偏多；训练侧亏一点，换来推理侧用更小的模型达到同等质量，省的是每一次推理的钱。</span></p><h3 id="三个样本的对照" tabindex="-1">三个样本的对照 <a class="header-anchor" href="#三个样本的对照" aria-label="Permalink to &quot;三个样本的对照&quot;">​</a></h3><p><a href="/llm/llama3-report">Llama 3</a> 披露了一条清晰的主线：稠密架构选型求稳、15.6T token 上 405B 是<strong>显式的过训决策</strong>——为推理效率故意偏离计算最优，配比与退火期的混合切换也有交代；但种子、完整消融与多数中间检查点不在披露范围。<a href="/llm/olmo2">OLMo 2</a> 走另一极：数据、代码、中间检查点、每个阶段的混合全部开放，稳定件组合（QK-Norm、z-loss、输出侧 RMSNorm）与中训多路 souping 都可对账——它是本课程各课能「逐课核对」的少数样本。<a href="/llm/fineweb-paper">FineWeb</a> 则示范数据侧配方怎么写成可消融的管线：每个过滤档位的效应单独发表。</p>',8)),(A(),o(l,null,{default:a(()=>[t(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%BB%E6%8A%A5%E5%91%8A%22%5D%20--%3E%20X%5B%22%E6%8A%BD%E5%86%B3%E7%AD%96%EF%BC%9A%E8%A7%84%E6%A8%A1%20%2F%20%E9%85%8D%E6%AF%94%20%2F%20%E8%B6%85%E5%8F%82%20%2F%20%E6%97%A5%E7%A8%8B%20%2F%20%E9%80%80%E7%81%AB%20%2F%20%E7%A8%B3%E5%AE%9A%E4%BB%B6%22%5D%0A%20%20X%20--%3E%20A%7B%22%E8%AF%A5%E5%86%B3%E7%AD%96%E6%8A%AB%E9%9C%B2%E5%88%B0%E5%93%AA%E4%B8%80%E7%BA%A7%EF%BC%9F%22%7D%0A%20%20A%20--%3E%7C%E6%95%B0%E5%AD%97%20%2B%20%E5%9D%90%E6%A0%87%E7%B3%BB%7C%20F%5B%22%E5%8F%AF%E5%AF%B9%E8%B4%A6%EF%BC%9A%E8%BF%9E%E5%9D%90%E6%A0%87%E4%B8%80%E8%B5%B7%E5%BC%95%E7%94%A8%22%5D%0A%20%20A%20--%3E%7C%E5%8F%AA%E6%9C%89%E6%95%B0%E5%AD%97%7C%20G%5B%22%E6%A0%87%E6%B3%A8%EF%BC%9A%E7%BB%91%E5%AE%9A%E5%9D%90%E6%A0%87%E7%B3%BB%E6%9C%AA%E7%9F%A5%22%5D%0A%20%20A%20--%3E%7C%E6%9C%AA%E6%8A%AB%E9%9C%B2%7C%20H%5B%22%E6%A0%87%E6%B3%A8%EF%BC%9A%E7%BB%93%E6%9E%84%E6%80%A7%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20F%20--%3E%20T%5B%22%E5%AF%B9%E7%85%A7%E8%A1%A8%EF%BC%9A%E6%9C%AC%E8%AF%BE%E7%A8%8B%E8%A6%81%E7%B4%A0%E9%80%90%E9%A1%B9%E6%89%93%E5%88%86%22%5D%0A%20%20G%20--%3E%20T%0A%20%20H%20--%3E%20T%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表按本课程要素排六行：规模与 \\(D/N\\) 分割（对照<a href="/llm/chinchilla">计算最优</a>与过训声明）、数据配比与清洗管线、优化器与超参迁移口径、学习率日程与退火结构、稳定件组合、评估门禁与污染声明。每行记三档：可对账（数字加坐标系）、半披露（只有数字）、缺失。读的时候问两个问题：这个数字<strong>绑定在什么上</strong>；这个缺失是<strong>能力问题还是刻意保密</strong>——两者对「能不能借鉴」的答案不同：前者可以推理补全，后者只能保守假设。</p><p><span class="marginnote">Llama 3.1 的 405B 用约 \\(3.8\\times 10^{25}\\) FLOPs 训了 15.6T token——按每参数约 20 token 的旧口诀是明显「过量」，报告把这笔账明写成推理效率决策；这是「过训 vs 等比」从隐性选择变成显式声明的范例。</span></p><p><span class="marginnote">直觉类比：读报告像看菜品评测——「盐 3 克」在不知道锅多大、几个人吃（坐标系）时没法照搬；真正可借鉴的是「先腌后炸」的工序（决策结构），那才是换了厨房也成立的东西。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么抽决策优于抄数字：配方要素之间的耦合意味着单点数字离开坐标系就没有语义——同一个峰值学习率在 WSD 与余弦下含义不同，同一份配比在不同清洗档位上不是同一份数据。开放配方的真正价值因此不是「数字可抄」，而是<strong>坐标系完整</strong>：OLMo 2 让你能核对「退火混合换没换、souping 拒没拒远点」，这些决策结构才是可迁移的知识。为什么报告不能当复现物：生产报告的写作目标是声明能力与边界，不是教学；把复现期望寄托在报告上，会系统性低估配方管理的工作量——这也是下一课把复现包从报告里独立出来的原因。</p><p><span class="marginnote">常见误区：初学者容易以为「开源模型 = 配方可复现」。权重公开不等于配方公开：没有数据配比、消融记录与中间检查点，复现仍要从头猜；OLMo 2 之所以珍贵，在于它把这几样一并开放。</span></p>',7)),(A(),o(l,null,{default:a(()=>[t(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E6%8A%A5%E5%91%8A%E6%95%B0%E5%AD%97%EF%BC%9A%E5%B3%B0%E5%80%BC%E5%AD%A6%E4%B9%A0%E7%8E%87%203e-4%22%5D%20--%3E%20C1%5B%22%E5%9D%90%E6%A0%87%E7%B3%BB%E4%B8%80%EF%BC%9AWSD%20%E6%97%A5%E7%A8%8B%22%5D%0A%20%20N%20--%3E%20C2%5B%22%E5%9D%90%E6%A0%87%E7%B3%BB%E4%BA%8C%EF%BC%9A%E4%BD%99%E5%BC%A6%E6%97%A5%E7%A8%8B%22%5D%0A%20%20N%20--%3E%20C3%5B%22%E5%9D%90%E6%A0%87%E7%B3%BB%E4%B8%89%EF%BC%9A%E4%B8%8D%E5%90%8C%20batch%20%E4%B8%8E%E5%BA%8F%E5%88%97%E9%95%BF%22%5D%0A%20%20C1%20--%3E%20M1%5B%22%E5%90%AB%E4%B9%89%EF%BC%9A%E7%A8%B3%E5%AE%9A%E6%AE%B5%E7%9A%84%E5%B9%B3%E5%8F%B0%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20C2%20--%3E%20M2%5B%22%E5%90%AB%E4%B9%89%EF%BC%9A%E5%85%A8%E7%A8%8B%E7%9A%84%E5%B9%B3%E5%9D%87%E6%AD%A5%E9%95%BF%22%5D%0A%20%20C3%20--%3E%20M3%5B%22%E5%90%AB%E4%B9%89%EF%BC%9A%E4%B8%8E%E6%A2%AF%E5%BA%A6%E5%99%AA%E5%A3%B0%E5%B0%BA%E5%BA%A6%E7%BB%91%E5%AE%9A%22%5D%0A%20%20M1%20--%3E%20Z%5B%22%E7%A6%BB%E5%BC%80%E5%9D%90%E6%A0%87%E7%B3%BB%EF%BC%9A%E4%B8%89%E4%B8%AA%E6%95%B0%E4%B8%8D%E5%8F%AF%E4%BA%92%E6%8D%A2%22%5D%0A%20%20M2%20--%3E%20Z%0A%20%20M3%20--%3E%20Z%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p>这张图回答的是「为什么单点数字离开坐标系就没有语义」：同一个数在不同日程、不同 batch 下承担的角色不同，抽数字必须连坐标一起抽。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课对照的是预训练段配方；后训练（RM、SFT、DPO、RLVR）的披露结构不同，各有专课。安全评测的披露深度在各对齐评测课，不在这里评分。社区榜单的公信力问题（分数怎么被指标与实现摆布）见<a href="/llm/eco-community-benchmark-credibility">社区基准的公信力</a>。许可证对「借鉴什么」的法律约束是<a href="/llm/eco-license-spectrum">开源生态</a>的课题——本课的技术对照不构成使用授权。最后，对照结论会过时：下一份报告可能改变某个要素的工业默认值，对照表按配方版本维护，不写成永恒结论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>读报告抽决策不抄数字：每个数字绑定坐标系，离开坐标系没有语义。</li><li>对照表六行：规模分割、配比管线、超参迁移、日程退火、稳定件、评估声明；各记披露档位。</li><li>Llama 3 示范显式过训声明，OLMo 2 示范全开放可对账，FineWeb 示范数据侧可消融管线。</li><li>缺失要区分能力问题与刻意保密；两者的借鉴策略不同。</li><li>出处：Grattafiori et al., Llama 3, arXiv:2407.21783；OLMo Team, arXiv:2501.00656；Penedo et al., FineWeb。</li></ul>',5))])}const f=n(p,[["render",m]]);export{_ as __pageData,f as default};
